import sys

def main():
    text = sys.stdin.read()
    chars = [c for c in text if not c.isspace()]
    board = [[0] * 4 for _ in range(4)]
    for idx, c in enumerate(chars[:16]):
        i = idx // 4
        j = idx % 4
        if c == 'x':
            board[i][j] = 1
        elif c == 'o':
            board[i][j] = -3
        else:
            board[i][j] = 0

    # horizontal
    for i in range(4):
        for j in range(2):
            if board[i][j] + board[i][j+1] + board[i][j+2] == 2:
                print("YES")
                return
    # vertical
    for j in range(4):
        for i in range(2):
            if board[i][j] + board[i+1][j] + board[i+2][j] == 2:
                print("YES")
                return
    # main diagonal
    for i in range(2):
        for j in range(2):
            if board[i][j] + board[i+1][j+1] + board[i+2][j+2] == 2:
                print("YES")
                return
    # anti-diagonal
    for i in range(2, 4):
        for j in range(2):
            if board[i][j] + board[i-1][j+1] + board[i-2][j+2] == 2:
                print("YES")
                return
    print("NO")

if __name__ == "__main__":
    main()

