import sys

def main():
    data = sys.stdin.read().split()
    # If input is given as lines without spaces, split() will split by whitespace, giving each line as a string.
    # But if there are spaces between characters, split() will give each character.
    # We need exactly 16 characters 'x', 'o', or '.'.
    chars = []
    for token in data:
        for ch in token:
            if ch in ('x', 'o', '.'):
                chars.append(ch)
    # If we have more than 16, take first 16.
    chars = chars[:16]
    # If less, maybe input is given as 4 lines of 4 chars each without spaces.
    # But split() on "xox.\nxo..\n....\n...." gives ['xox.', 'xo..', '....', '....'].
    # The above loop will break each string into chars.
    # So it should work.

    board = [[0]*4 for _ in range(4)]
    idx = 0
    for i in range(4):
        for j in range(4):
